using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works:
var json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-tripped: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false when
//    the resolver doesn't support the requested type.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded: {found!.Type.Name}");

if (!limited.TryGetTypeInfo(typeof(int), out _))
    Console.WriteLine("TryGetTypeInfo(int) returned false — no exception thrown.");

// --- Supporting types ---

record Person(string Name, int Age);

/// A resolver that only knows about Person.
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private static readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}

